-- canonical-case-start Ethereum
WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Ethereum","sources":[{"id":"eth-llama","title":"Ethereum chain metrics","publisher":"DefiLlama","url":"https://defillama.com/chain/ethereum","source_role":"independent-data","checked_at":"2026-07-29"},{"id":"eth-roadmap","title":"Ethereum roadmap","publisher":"Ethereum Foundation","url":"https://ethereum.org/roadmap/","source_role":"primary","checked_at":"2026-07-29"},{"id":"eth-scaling","title":"Scaling Ethereum","publisher":"Ethereum Foundation","url":"https://ethereum.org/roadmap/scaling/","source_role":"primary","checked_at":"2026-07-29"},{"id":"eth-priorities","title":"Protocol priorities update for 2026","publisher":"Ethereum Foundation","url":"https://blog.ethereum.org/2026/02/18/protocol-priorities-update-2026","source_role":"primary","checked_at":"2026-07-29"},{"id":"eth-build","title":"Why build on Ethereum","publisher":"Ethereum Foundation","url":"https://ethereum.org/latest/why-build-on-ethereum/","source_role":"primary","checked_at":"2026-07-29"}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"Ethereum is a thriving, dominant settlement and collateral network rather than an unqualified execution winner. The July 29 snapshot records deep DeFi, stablecoin and tokenized-asset bases, while the protocol deliberately pushes much transaction execution to rollups. That makes L1-only fee or transaction comparisons incomplete and makes value capture from the rollup economy the central open question.","confidence":"high","as_of":"2026-07-29","source_refs":["eth-llama","eth-roadmap","eth-scaling"]},"why":{"summary":"Observed: Ethereum accumulated the deepest reviewed collateral and settlement base, has continued upgrading without a recorded full-network halt, and explicitly follows a rollup-centric roadmap. Strategic inference: its durability comes from choosing neutral settlement, multi-client fault isolation, conservative community-governed upgrades and cheap data availability for rollups instead of maximizing base-layer throughput. Those choices reinforced developer standards, liquidity and credible neutrality, but they also dispersed execution, users and fee capture across L2s. The success is therefore causal and conditional: standards plus security created the moat; rollup specialization preserved accessibility while creating fragmentation and an unresolved division of economics among ETH, L1 validators, applications and sequencers.","confidence":"medium","source_refs":["eth-roadmap","eth-scaling","eth-priorities","eth-build","eth-llama"]},"strategic_choices":[{"decision":"Replace proof of work with proof of stake through the Merge.","consequence":"Energy use and issuance fell and staked ETH became the security budget; the trade-off moved concentration and correlated-provider risk into staking infrastructure.","confidence":"high","source_refs":["eth-roadmap","eth-build"]},{"decision":"Adopt a rollup-centric scaling roadmap and introduce blob data.","consequence":"L2 transaction capacity and cost improved without forcing every home node to execute every user transaction, while execution economics and user state fragmented across rollups.","confidence":"high","source_refs":["eth-scaling","eth-priorities"]},{"decision":"Maintain multiple execution and consensus clients.","consequence":"Implementation diversity limits one-client failure blast radius, but actual protection still depends on balanced client and operator shares rather than the number of codebases.","confidence":"high","source_refs":["eth-build"]},{"decision":"Prioritize conservative, community-coordinated protocol upgrades over a single operator roadmap.","consequence":"The network gained resilience and credible neutrality at the cost of slower coordination and unresolved governance during extreme failures.","confidence":"medium","source_refs":["eth-roadmap","eth-priorities"]}],"counterfactual":{"summary":"A monolithic high-throughput L1 might have retained more execution fees and simpler composability, but would likely have raised node requirements and weakened the accessibility and client diversity supporting Ethereum’s trust premium. Rejecting rollups would also have left Base- and Arbitrum-class demand facing materially higher costs. The evidence does not establish the net counterfactual value captured by either design.","confidence":"medium","source_refs":["eth-scaling","eth-build","eth-priorities"]},"watch":[{"signal":"Ethereum and L2 TVL, stablecoins, tokenized assets, blobs, fees and transactions measured together.","implication":"Growth on L2s with stagnant L1 fees can still validate settlement demand, but may weaken direct ETH value capture.","source_refs":["eth-llama","eth-scaling"]},{"signal":"Delivery and utilization of PeerDAS, blob-scaling and the published protocol-priority roadmap.","implication":"Successful capacity increases strengthen rollup settlement; delay or sustained underuse weakens the scaling thesis.","source_refs":["eth-priorities","eth-scaling"]},{"signal":"Execution-client, consensus-client, staking-provider and cloud concentration.","implication":"Safety depends on independent control distribution; a dominant client or operator creates correlated fault risk.","source_refs":["eth-build"]}],"unknowns":[{"question":"What share of rollup economic value ultimately accrues to ETH and L1 security?","resolution_trigger":"Publish a reproducible L1/L2 fee, MEV, issuance and sequencer-profit attribution series."},{"question":"When will major rollups decentralize sequencing and proving without degrading exits?","resolution_trigger":"Verified production milestones and measured operator diversity."},{"question":"Who beneficially controls stake across pools, operators and infrastructure providers?","resolution_trigger":"Independent entity-resolution audit of validator and delegation ownership."},{"question":"How would extreme-case social slashing be governed in practice?","resolution_trigger":"A tested, public incident-governance procedure or real event postmortem."}],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
      facts.data,
      '$.forensic_analysis',
      json(json_extract((SELECT payload FROM causal_seed), '$.forensic_analysis'))
    )
    WHEN '_meta' THEN json_set(
      facts.data,
      '$.forensic_analysis_version', 'forensic-analysis-v1',
      '$.last_reviewed', '2026-07-29',
      '$.next_review_at',
      json_extract(
        (SELECT payload FROM causal_seed),
        '$.forensic_analysis.review.next_review_at'
      )
    )
    ELSE facts.data
  END
  ,
  sources = CASE
    WHEN facts.dimension = 'synthesis' THEN (
      SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_set(
                json_patch(old_source.value, new_source.value),
                '$.checked_at',
                CASE
                  WHEN json_extract(old_source.value, '$.checked_at')
                    > json_extract(new_source.value, '$.checked_at')
                    THEN json_extract(old_source.value, '$.checked_at')
                  ELSE COALESCE(
                    json_extract(new_source.value, '$.checked_at'),
                    json_extract(old_source.value, '$.checked_at')
                  )
                END
              )
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
            ON json_extract(new_source.value, '$.url')
              = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
            OR old_source.key = (
              SELECT MIN(candidate.key)
              FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
              WHERE json_extract(candidate.value, '$.url')
                = json_extract(old_source.value, '$.url')
            )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
          WHERE NOT EXISTS (
            SELECT 1
            FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url')
              = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )
    )
    ELSE facts.sources
  END
  ,
  updated_at = '2026-07-29'
WHERE facts.chain = json_extract((SELECT payload FROM causal_seed), '$.chain')
  AND facts.dimension IN ('synthesis', '_meta');
-- canonical-case-end Ethereum

