-- canonical-case-start BSC
WITH causal_seed(payload) AS (
  VALUES ('{"chain":"BSC","sources":[{"id":"bsc-llama","title":"BSC chain metrics","publisher":"DefiLlama","url":"https://defillama.com/chain/bsc?currency=USD","source_role":"independent-data","checked_at":"2026-07-29"},{"id":"bsc-consensus","title":"BNB Smart Chain introduction","publisher":"BNB Chain","url":"https://docs.bnbchain.org/bnb-smart-chain/introduction/","source_role":"primary","checked_at":"2026-07-29"},{"id":"bsc-roadmap","title":"BNB Chain H2 2026 technical roadmap","publisher":"BNB Chain","url":"https://www.bnbchain.org/en/blog/bnb-chain-h2-2026-tech-roadmap-doubling-down-on-speed","source_role":"primary","checked_at":"2026-07-29"},{"id":"bsc-mev","title":"Malicious MEV reduction","publisher":"BNB Chain","url":"https://www.bnbchain.org/en/blog/malicious-mev-reduction","source_role":"primary","checked_at":"2026-07-29"}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"BSC is a thriving mass-market EVM trading and stablecoin chain with high observed activity. Its success is paired with a persistent concentration discount: the small elected validator set and Binance-adjacent distribution produce speed and liquidity, but weaken the credible-neutrality case compared with broader validator networks. Activity does not erase this governance trade-off.","confidence":"high","as_of":"2026-07-29","source_refs":["bsc-llama","bsc-consensus","bsc-roadmap"]},"why":{"summary":"Observed: BSC combines large stablecoin liquidity and DEX volume with low fees, EVM compatibility and a limited proof-of-staked-authority validator set. Strategic inference: the chain won retail flow by minimizing migration cost for Ethereum applications, using BNB incentives and exchange-adjacent wallet/liquidity distribution, and repeatedly optimizing block time, clients and gas pricing for trading. That coordinated design can ship performance changes and incident responses quickly. It also concentrates validator selection, governance and brand risk, so the same coordination that creates speed can reduce neutrality and make external regulatory or operational shocks propagate. Low fees were necessary but not sufficient: pre-existing users, assets and applications supplied the distribution flywheel that technically similar chains lacked.","confidence":"medium","source_refs":["bsc-llama","bsc-consensus","bsc-roadmap","bsc-mev"]},"strategic_choices":[{"decision":"Use a limited, stake-ranked proof-of-staked-authority validator set.","consequence":"A small active set supports predictable sub-second execution and coordinated slashing, while concentrating consensus and governance power.","confidence":"high","source_refs":["bsc-consensus"]},{"decision":"Preserve EVM compatibility while aggressively reducing gas costs and block times.","consequence":"Ethereum applications and users migrated cheaply and trading throughput grew, while state growth and validator economics became continuing engineering constraints.","confidence":"high","source_refs":["bsc-roadmap"]},{"decision":"Treat malicious MEV as a coordinated builder, validator, governance and protected-RPC problem.","consequence":"The ecosystem can intervene quickly, but operator-reported reduction claims require independent reproducibility and may hide displacement.","confidence":"medium","source_refs":["bsc-mev","bsc-roadmap"]},{"decision":"Leverage BNB and Binance-adjacent liquidity instead of building distribution from zero.","consequence":"The chain gained a powerful retail funnel and asset base, while inheriting brand, access and regulatory concentration risk.","confidence":"medium","source_refs":["bsc-llama","bsc-consensus"]}],"counterfactual":{"summary":"A much larger, permissionlessly rotating validator set could improve credible neutrality but might slow the exact coordinated execution profile that won retail trading flow. Without Binance-adjacent liquidity and wallet distribution, low fees and EVM compatibility alone would probably not have produced the same scale. The evidence does not isolate the independent causal contribution of brand, incentives and technology.","confidence":"medium","source_refs":["bsc-llama","bsc-consensus","bsc-roadmap"]},"watch":[{"signal":"DEX volume, stablecoin supply, active addresses and application revenue per transaction.","implication":"Paid retained demand matters more than benchmark TPS or raw transactions.","source_refs":["bsc-llama"]},{"signal":"Validator beneficial ownership, stake concentration, client mix and slash incidents.","implication":"Concentrated control or correlated clients widen the safety discount.","source_refs":["bsc-consensus"]},{"signal":"Realized finality, fees, state growth and validator yield after roadmap changes.","implication":"Performance gains are durable only if independent validators can economically operate them.","source_refs":["bsc-roadmap"]}],"unknowns":[{"question":"Who beneficially controls the elected validators and their major delegations?","resolution_trigger":"Independent entity-resolution and infrastructure audit."},{"question":"Can the claimed malicious-MEV reduction be reproduced independently?","resolution_trigger":"Published methodology and third-party block-level replication."},{"question":"Is validator security budget sustainable after large gas-price cuts?","resolution_trigger":"Operator cost, reward and exit data by cohort."},{"question":"What trust and migration assumptions accompany the proposed next-generation architecture?","resolution_trigger":"Production specifications, audits and transition plan."}],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
      facts.data,
      '$.forensic_analysis',
      json(json_extract((SELECT payload FROM causal_seed), '$.forensic_analysis'))
    )
    WHEN '_meta' THEN json_set(
      facts.data,
      '$.forensic_analysis_version', 'forensic-analysis-v1',
      '$.last_reviewed', '2026-07-29',
      '$.next_review_at',
      json_extract(
        (SELECT payload FROM causal_seed),
        '$.forensic_analysis.review.next_review_at'
      )
    )
    ELSE facts.data
  END
  ,
  sources = CASE
    WHEN facts.dimension = 'synthesis' THEN (
      SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_set(
                json_patch(old_source.value, new_source.value),
                '$.checked_at',
                CASE
                  WHEN json_extract(old_source.value, '$.checked_at')
                    > json_extract(new_source.value, '$.checked_at')
                    THEN json_extract(old_source.value, '$.checked_at')
                  ELSE COALESCE(
                    json_extract(new_source.value, '$.checked_at'),
                    json_extract(old_source.value, '$.checked_at')
                  )
                END
              )
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
            ON json_extract(new_source.value, '$.url')
              = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
            OR old_source.key = (
              SELECT MIN(candidate.key)
              FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
              WHERE json_extract(candidate.value, '$.url')
                = json_extract(old_source.value, '$.url')
            )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
          WHERE NOT EXISTS (
            SELECT 1
            FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url')
              = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )
    )
    ELSE facts.sources
  END
  ,
  updated_at = '2026-07-29'
WHERE facts.chain = json_extract((SELECT payload FROM causal_seed), '$.chain')
  AND facts.dimension IN ('synthesis', '_meta');
-- canonical-case-end BSC

