-- canonical-case-start Tron
WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Tron","sources":[{"id":"tron-llama","title":"Tron chain metrics","publisher":"DefiLlama","url":"https://defillama.com/chain/tron","source_role":"independent-data","checked_at":"2026-07-29"},{"id":"tron-resource","title":"TRON resource model","publisher":"TRON DAO","url":"https://developers.tron.network/docs/resource-model","source_role":"primary","checked_at":"2026-07-29"},{"id":"tron-sr","title":"TRON super representatives","publisher":"TRON DAO","url":"https://developers.tron.network/docs/super-representatives","source_role":"primary","checked_at":"2026-07-29"},{"id":"tron-economics","title":"TRON economic model","publisher":"TRON DAO","url":"https://developers.tron.network/docs/tron-economic-model","source_role":"primary","checked_at":"2026-07-29"}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"Tron is a thriving but narrow and concentrated stablecoin-transfer rail. The reviewed snapshot shows very large stablecoin balances and active addresses relative to a much smaller DEX economy, with USDT dominating the stablecoin mix. Success in low-cost transfers should not be generalized into broad application diversity or decentralized governance.","confidence":"high","as_of":"2026-07-29","source_refs":["tron-llama","tron-resource","tron-sr"]},"why":{"summary":"Observed: Tron supports a very large stablecoin base and frequent transfers through a bandwidth-and-energy resource model, TRC-20 compatibility and 27 elected block-producing super representatives. Strategic inference: the network optimized for cheap, predictable token movement and exchange settlement rather than a maximally broad validator set or differentiated application stack. That fit USDT distribution exceptionally well, and issuer, exchange and user liquidity reinforced one another until the payment rail became difficult to displace. The cost is concentration: one stablecoin issuer dominates balances, 27 producers coordinate consensus, and a narrow use case can mask shallow application diversity. Tron succeeded because it found a repeat transactional killer app; that success remains exposed to issuer policy, beneficial validator control and competing payment rails.","confidence":"medium","source_refs":["tron-llama","tron-resource","tron-sr","tron-economics"]},"strategic_choices":[{"decision":"Use bandwidth and energy resources obtained through staking or delegation, with TRX burn as fallback.","consequence":"Frequent transfers receive predictable economics and a resource-rental market, while users inherit complexity and intermediated resource pricing.","confidence":"high","source_refs":["tron-resource","tron-economics"]},{"decision":"Limit block production to 27 elected super representatives.","consequence":"Three-second production and fast parameter coordination become practical, while consensus and governance power remain concentrated.","confidence":"high","source_refs":["tron-sr"]},{"decision":"Prioritize EVM-compatible TRC-20 token and stablecoin rails.","consequence":"Existing wallets and exchanges could support USDT transfers at scale, but one issuer and use case dominate the economic profile.","confidence":"high","source_refs":["tron-llama","tron-economics"]},{"decision":"Make transaction resources and fees adjustable through representative governance.","consequence":"The chain can respond to congestion and economics quickly, while large voters and producers gain material policy influence.","confidence":"medium","source_refs":["tron-sr","tron-resource"]}],"counterfactual":{"summary":"A broader validator set could improve neutrality but raise coordination and latency costs. Without early USDT and exchange distribution, the resource model alone likely would not have produced the same transfer network effect. A more diversified application strategy might reduce issuer dependence, but could also dilute the cheap-transfer specialization that made the chain successful.","confidence":"medium","source_refs":["tron-llama","tron-resource","tron-sr"]},"watch":[{"signal":"Stablecoin supply by issuer, transfer growth, active addresses, fees and diversified application volume.","implication":"Transfer growth with broader paid applications strengthens durability; greater issuer concentration increases fragility.","source_refs":["tron-llama"]},{"signal":"Super-representative vote concentration, turnover and shared infrastructure.","implication":"Independent and rotating producers narrow the governance discount; coordinated control widens it.","source_refs":["tron-sr"]},{"signal":"Energy pricing, rental demand, TRX burn and transfer cost versus competing rails.","implication":"The killer app persists only while users retain a cost and distribution advantage.","source_refs":["tron-resource","tron-economics"]}],"unknowns":[{"question":"Who beneficially controls the 27 super representatives and largest voters?","resolution_trigger":"Independent entity and infrastructure-resolution audit."},{"question":"What share of transfers represents external commerce rather than exchange movement or automation?","resolution_trigger":"Entity-adjusted flow classification and sampled user cohorts."},{"question":"How sensitive is activity to Tether issuance, redemption and compliance policy?","resolution_trigger":"Issuer scenario analysis and observed policy-event responses."},{"question":"Who captures margins in the energy-rental market and how concentrated is supply?","resolution_trigger":"Address-level market-share and profitability analysis."}],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
