WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Bitcoin","sources":[{"id":"btc-paper","title":"Bitcoin: A Peer-to-Peer Electronic Cash System","publisher":"Satoshi Nakamoto","url":"https://bitcoin.org/bitcoin.pdf","source_role":"primary-historical","checked_at":"2026-07-29"},{"id":"btc-core","title":"About Bitcoin Core","publisher":"Bitcoin Core","url":"https://bitcoincore.org/en/about/","source_role":"primary","checked_at":"2026-07-29"},{"id":"btc-consensus","title":"Bitcoin consensus amount constants","publisher":"Bitcoin Core","url":"https://github.com/bitcoin/bitcoin/blob/master/src/consensus/amount.h","source_role":"primary","checked_at":"2026-07-29"},{"id":"btc-dev","title":"Bitcoin transaction developer guide","publisher":"Bitcoin.org","url":"https://developer.bitcoin.org/devguide/transactions.html","source_role":"primary","checked_at":"2026-07-29"},{"id":"btc-cve","title":"CVE-2018-17144 disclosure","publisher":"Bitcoin Core","url":"https://bitcoincore.org/en/2018/09/20/notice/","source_role":"primary","checked_at":"2026-07-29"}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"Bitcoin is a successful monetary-settlement L1 and the control case for a chain without a company treasury, token sale or native DeFi-TVL metric. The outcome rests on continued protocol operation and the durability of proof-of-work settlement, not on wrapped-BTC application TVL. This dossier deliberately withholds current market, hash-rate and fee conclusions not covered by its dated source set.","confidence":"high","as_of":"2026-07-29","source_refs":["btc-paper","btc-core","btc-consensus","btc-dev"]},"why":{"summary":"Observed: Bitcoin has operated since 2009 under a proof-of-work consensus model, uses a native scarce fee asset, and is maintained through open-source client development rather than a protocol company. Strategic inference: its durability comes from choosing a deliberately narrow monetary function, simple validation rules, costly proof-of-work history and the ability for users to verify with their own software. Avoiding a foundation-led roadmap and rich base-layer application environment reduced governance and execution complexity, while limiting throughput and pushing custody, payments and applications into external layers. The success is not “oldest therefore best”: the design created a credible, hard-to-change settlement asset and social coordination norm. Its long-run weakness is the same narrowness—security must increasingly rely on fee demand, and many users depend on concentrated miners, pools and custodians outside consensus.","confidence":"medium","source_refs":["btc-paper","btc-core","btc-consensus","btc-dev","btc-cve"]},"strategic_choices":[{"decision":"Use proof of work and accumulated chain work to order transactions.","consequence":"Open participation and costly history support censorship resistance, while security consumes resources and depends on economically independent hash power.","confidence":"high","source_refs":["btc-paper"]},{"decision":"Embed rule-based issuance and transition miner incentives toward transaction fees.","consequence":"Predictable monetary rules strengthen scarcity, while declining subsidy makes future fee demand a material security-budget question.","confidence":"high","source_refs":["btc-paper","btc-consensus"]},{"decision":"Keep the base protocol narrow instead of adding a general smart-contract VM.","consequence":"Validation remains comparatively auditable and stable, while applications and higher-throughput payments move to layers with separate trust assumptions.","confidence":"medium","source_refs":["btc-dev","btc-core"]},{"decision":"Rely on open-source maintainers and voluntary node adoption rather than an owner-controlled upgrade process.","consequence":"No entity can unilaterally rewrite consensus, but upgrades and emergencies require slow social coordination and concentrated maintainer review.","confidence":"high","source_refs":["btc-core","btc-cve"]}],"counterfactual":{"summary":"A richer VM and faster base-layer blocks could have attracted more application fees and native activity, but likely increased node resource demands, attack surface and contentious governance. A foundation treasury could coordinate development faster while creating an identifiable control point. The sources do not establish whether those alternatives would improve the current security budget or weaken the trust-minimized settlement property.","confidence":"medium","source_refs":["btc-paper","btc-core","btc-dev","btc-cve"]},"watch":[{"signal":"Fee revenue relative to block subsidy across full market cycles.","implication":"A durable fee market supports the post-subsidy security thesis; weak fees increase dependence on issuance and miner economics.","source_refs":["btc-paper","btc-consensus"]},{"signal":"Hash-rate, mining-pool and infrastructure concentration from dated independent data.","implication":"Concentration can undermine the assumption that honest control is broadly distributed.","source_refs":["btc-paper"]},{"signal":"Critical client vulnerabilities, adoption of fixes and implementation diversity.","implication":"Rapid remediation limits consensus risk; unpatched correlated clients widen it.","source_refs":["btc-cve","btc-core"]}],"unknowns":[{"question":"What is the current beneficial concentration of hash power?","resolution_trigger":"Entity-resolved pool, facility and financing data."},{"question":"Will transaction fees support an adequate security budget as subsidy declines?","resolution_trigger":"Multi-cycle fee, hash-price and attack-cost modeling."},{"question":"How concentrated is practical user custody and transaction access?","resolution_trigger":"Audited custodian and wallet market shares across jurisdictions."},{"question":"How distributed is effective influence over Bitcoin Core changes?","resolution_trigger":"Maintainer, reviewer, funding and node-adoption analysis."}],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-29","reviewer":"chaindump-research-desk"}}}')
)
