-- canonical-case-start OP Mainnet
WITH causal_seed(payload) AS (
  VALUES ('{"chain":"OP Mainnet","sources":[{"id":"op-mainnet","title":"What is OP Mainnet?","publisher":"Optimism","url":"https://optimism.io/blog/what-is-op-mainnet","source_role":"primary","checked_at":"2026-07-29"},{"id":"op-stack","title":"OP Stack introduction","publisher":"Optimism","url":"https://docs.optimism.io/op-stack/introduction/op-stack","source_role":"primary","checked_at":"2026-07-29"},{"id":"op-chapter","title":"Optimism: A New Chapter","publisher":"Optimism","url":"https://optimism.io/blog/a-new-chapter","source_role":"primary","checked_at":"2026-07-29"},{"id":"op-tvl","title":"Optimism historical TVL","publisher":"DefiLlama","url":"https://api.llama.fi/v2/historicalChainTvl/Optimism","source_role":"independent-data","checked_at":"2026-07-29"},{"id":"op-fees","title":"Optimism fee metrics","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Optimism?dataType=dailyFees","source_role":"independent-data","checked_at":"2026-07-29"},{"id":"op-cg","title":"OP market data","publisher":"CoinGecko","url":"https://api.coingecko.com/api/v3/coins/optimism","source_role":"independent-data","checked_at":"2026-07-29"}],"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"OP Mainnet is a successful Ethereum L2 and the reference deployment for a widely adopted rollup stack, but it no longer owns all economic activity created by that stack. The reviewed snapshot shows meaningful fees and TVL alongside large drawdowns in network liquidity and OP price. ETH pays gas, so network usage and OP token value capture require separate conclusions.","confidence":"high","as_of":"2026-07-29","source_refs":["op-mainnet","op-stack","op-tvl","op-fees","op-cg"]},"why":{"summary":"Observed: OP Mainnet reduced Ethereum execution costs, the OP Stack became infrastructure for multiple chains including stronger-distribution competitors, and the Collective uses OP for governance while ETH remains the gas asset. Strategic inference: Optimism chose platform distribution over protecting one chain’s exclusive market share. Open, reusable software and Superchain coordination multiplied adoption and public-goods influence, but also enabled activity to migrate to other OP chains, especially those with superior consumer funnels. The product strategy succeeded at the stack level; OP Mainnet’s own TVL and token performance show that stack success does not automatically create local liquidity or token demand. This is a deliberate value-capture trade-off, not simply competitive failure. The next causal test is whether shared sequencing, interoperability and revenue mechanisms return measurable economics to the Collective and OP.","confidence":"medium","source_refs":["op-mainnet","op-stack","op-chapter","op-tvl","op-fees","op-cg"]},"strategic_choices":[{"decision":"Use an optimistic rollup with Ethereum data and settlement.","consequence":"Applications gained lower-cost EVM execution, while users retained proof, sequencer and upgrade assumptions beyond Ethereum L1.","confidence":"high","source_refs":["op-mainnet","op-stack"]},{"decision":"Open the OP Stack for other chains rather than keep the technology proprietary.","consequence":"Ecosystem distribution expanded dramatically, while OP Mainnet invited competition from deployments using the same stack.","confidence":"high","source_refs":["op-stack","op-chapter"]},{"decision":"Use ETH for gas and OP for governance.","consequence":"Ethereum alignment and user onboarding improved, but routine transaction demand does not mechanically create OP buy pressure.","confidence":"high","source_refs":["op-mainnet","op-cg"]},{"decision":"Pursue a Superchain of coordinated chains and shared standards.","consequence":"Network effects may emerge through interoperability and shared economics, while execution and liquidity fragment before those mechanisms mature.","confidence":"medium","source_refs":["op-stack","op-chapter"]}],"counterfactual":{"summary":"Keeping the stack proprietary might have protected OP Mainnet share and short-term fees, but would likely have reduced distribution and Superchain relevance. Making OP the gas asset could strengthen direct demand while increasing onboarding friction and weakening ETH alignment. A narrower application strategy might create stickier local use but sacrifice infrastructure leadership.","confidence":"medium","source_refs":["op-stack","op-chapter","op-mainnet"]},"watch":[{"signal":"OP Mainnet TVL, fees, users and net flows relative to Base and other OP Stack chains.","implication":"Local retention distinguishes a successful chain from a successful shared stack.","source_refs":["op-tvl","op-fees"]},{"signal":"Interoperability, shared sequencing and revenue contributions across the Superchain.","implication":"Production economic flows must validate the collective value-capture thesis.","source_refs":["op-stack","op-chapter"]},{"signal":"Governance participation and OP-linked economic rights beyond grants.","implication":"Durable token relevance requires measurable control or cash-flow utility, not stack branding alone.","source_refs":["op-chapter","op-cg"]}],"unknowns":[{"question":"How much OP Stack value returns to the Collective and OP holders?","resolution_trigger":"Audited chain-by-chain revenue and governance-right attribution."},{"question":"Can Superchain interoperability reduce fragmentation in production?","resolution_trigger":"Measured cross-chain UX, latency, failure and liquidity data."},{"question":"What share of OP Mainnet users are retained independent of incentives?","resolution_trigger":"Application and wallet cohorts around grant changes."},{"question":"When will sequencing and upgrade authority become materially decentralized?","resolution_trigger":"Verified contract and operator milestones."}],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
      facts.data,
      '$.forensic_analysis',
      json(json_extract((SELECT payload FROM causal_seed), '$.forensic_analysis'))
    )
    WHEN '_meta' THEN json_set(
      facts.data,
      '$.forensic_analysis_version', 'forensic-analysis-v1',
      '$.last_reviewed', '2026-07-29',
      '$.next_review_at',
      json_extract(
        (SELECT payload FROM causal_seed),
        '$.forensic_analysis.review.next_review_at'
      )
    )
    ELSE facts.data
  END
  ,
  sources = CASE
    WHEN facts.dimension = 'synthesis' THEN (
      SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_set(
                json_patch(old_source.value, new_source.value),
                '$.checked_at',
                CASE
                  WHEN json_extract(old_source.value, '$.checked_at')
                    > json_extract(new_source.value, '$.checked_at')
                    THEN json_extract(old_source.value, '$.checked_at')
                  ELSE COALESCE(
                    json_extract(new_source.value, '$.checked_at'),
                    json_extract(old_source.value, '$.checked_at')
                  )
                END
              )
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
            ON json_extract(new_source.value, '$.url')
              = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
            OR old_source.key = (
              SELECT MIN(candidate.key)
              FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
              WHERE json_extract(candidate.value, '$.url')
                = json_extract(old_source.value, '$.url')
            )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
          WHERE NOT EXISTS (
            SELECT 1
            FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url')
              = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )
    )
    ELSE facts.sources
  END
  ,
  updated_at = '2026-07-29'
WHERE facts.chain = json_extract((SELECT payload FROM causal_seed), '$.chain')
  AND facts.dimension IN ('synthesis', '_meta');
-- canonical-case-end OP Mainnet

